img = uint8(magic(8)*3);
t = Tiff('pages_demo.tif','w');
for k = 1:2
  page = img;
  if k == 2, page = 255 - img; end
  t.setTag('ImageLength',8); t.setTag('ImageWidth',8);
  t.setTag('Photometric',Tiff.Photometric.MinIsBlack);
  t.setTag('BitsPerSample',8); t.setTag('SamplesPerPixel',1);
  t.setTag('PlanarConfiguration',Tiff.PlanarConfiguration.Chunky);
t.setTag('RowsPerStrip',8);
  t.write(page);
  if k < 2, t.writeDirectory(); end
end
t.close();
r = Tiff('pages_demo.tif','r');
a = r.read();
r.nextDirectory();
b = r.read();
r.close();
disp(a(1,1:3))
disp(b(1,1:3))

img = uint8(magic(8)*3);
t = Tiff('strip_demo.tif','w');
t.setTag('ImageLength',8); t.setTag('ImageWidth',8);
t.setTag('Photometric',Tiff.Photometric.MinIsBlack);
t.setTag('BitsPerSample',8); t.setTag('SamplesPerPixel',1);
t.setTag('PlanarConfiguration',Tiff.PlanarConfiguration.Chunky);
t.setTag('RowsPerStrip',4);
t.writeEncodedStrip(1, img(1:4,:));
