t = Tiff('tile_demo.tif','w');
t.setTag('ImageLength',32); t.setTag('ImageWidth',32);
t.setTag('TileLength',16); t.setTag('TileWidth',16);
t.setTag('Photometric',Tiff.Photometric.MinIsBlack);
t.setTag('BitsPerSample',8); t.setTag('SamplesPerPixel',1);
t.setTag('PlanarConfiguration',Tiff.PlanarConfiguration.Chunky);
for k = 1:4
  t.writeEncodedTile(k, uint8(k*50*ones(16)));
end
t.close();
